49:     # 静态资源缓存
50:     # 文件名带内容 hash，可以长缓存；配合下方的 /index.html no-cache，
51:     # 发版后用户刷新即拿到新 HTML，chunk 命中本地缓存不重复下载。
52:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
53:         # 注意：add_header 会让本 location 不再继承上层 Cache-Control，
